  function panoramaTower(x,y,w,h,depth,p,seed=0){
    const front=['#344d62','#3e5365','#2e465c','#435867'][seed%4],side=['#20394e','#283f54','#213a4d'][seed%3];
    const cols=Math.max(2,Math.floor(w/21)-1),rows=Math.max(1,Math.floor((h-17)/27));
    const rooftopDetails=seed%3===0?`<path d="m${w*.51} ${-h-depth*.43} ${depth*.2} -${depth*.13} ${w*.25} 0 -${depth*.2} ${depth*.13}Z" fill="#668781" opacity=".65"/><path d="M${w*.73} ${-h-depth*.47}v-${depth*.3}" stroke="#8b9b9e" stroke-width="1.5"/>`:seed%3===1?`<path d="M${w*.72} ${-h-depth*.44}v-${depth*.32}h${w*.14}v${depth*.32}Z" fill="#536b78"/><path d="M${w*.72} ${-h-depth*.76}l${depth*.17} -${depth*.1}h${w*.14}l-${depth*.17} ${depth*.1}Z" fill="#788b90"/>`:'';
    return `<g class="rain-city-panorama-building" transform="translate(${x} ${y})">${path(`M0 0H${w}V${-h}H0Z`,front)}${path(`M${w} 0l${depth} -${depth*.62}V${-h-depth*.62}L${w} ${-h}Z`,side)}${path(`M0 ${-h} ${depth} ${-h-depth*.62} ${w+depth} ${-h-depth*.62} ${w} ${-h}Z`,p.roofDark)}<path d="M0 ${-h}H${w}l${depth} -${depth*.62}" stroke="${p.edge}" stroke-width="2" opacity=".65"/><path d="m${w*.25} ${-h-depth*.2} ${depth*.27} -${depth*.18} ${w*.32} 0 -${depth*.27} ${depth*.18}Z" fill="#78848a" opacity=".5"/>${rooftopDetails}${windows(12,-h+16,cols,rows,p,.77,seed)}${seed%2===0?`<g opacity=".52">${Array.from({length:Math.min(3,rows)},(_,r)=>`<path d="M${w*.54} ${-h+36+r*32}h${w*.33}v5h-${w*.33}Z" fill="#82989d"/><path d="M${w*.54} ${-h+34+r*32}v-8m${w*.16} 8v-8m${w*.17} 8v-8m-${w*.33} 0h${w*.33}" stroke="#a3b4b2" stroke-width="1.1"/>`).join('')}</g>`:''}<path d="M${w+depth*.4} ${-h+2}v${Math.max(1,h-depth*.5)}m${depth*.28} ${-Math.max(1,h-depth*.5)-8}v${Math.max(1,h-depth*.5)}" stroke="${p.window}" stroke-width="3" opacity=".09"/></g>`;
  }
